contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address minter, address from, address to, uint256 id) public {
        require(minter != address(0) && from != address(0) && to != address(0));
        require(to != address(0));

        // Mint id to `from` so that a transfer is possible.
        // _safeMint requires recipient to not reject ERC721 receipt; for EOAs code.length==0 so it's fine.
        // Use a try to skip if minting fails for any reason.
        bool minted;
        try c.mint(from, id) { minted = true; } catch { minted = false; }
        require(minted, "mint failed");

        // Setup: ensure `this` contract is authorized to transfer id from `from`.
        // We call approve from `from`'s perspective? c.approve uses msg.sender as owner.
        // But we need from's approval. Since c is owned by this test, we can't impersonate `from`.
        // Instead, we rely on the fact that c is PuttyV2Nft and has a public `transferFrom`
        // where authorization checks: msg.sender == from || isApprovedForAll[from][msg.sender] || msg.sender == getApproved[id].
        // msg.sender is this test contract. So we need either from == address(this) or an approval from `from`.
        // We can set from = address(this) to satisfy msg.sender == from.
        // So we require from == address(this) as precondition.
        require(from == address(this), "from must be this contract");

        // Now call transferFrom as this contract (which is `from`).
        c.transferFrom(from, to, id);

        // General rule: after a successful transferFrom, ownerOf(id) == to.
        assert(c.ownerOf(id) == to);
    }

    receive() external payable {}
}

